  function historyCloze(prompt, fields, explanation) {
    const steps = fields.map(([label, answer, ...aliases])=>({label,answer,aliases,text:true}));
    return {prompt,steps,options:null,correct:steps.map(step=>step.answer).join(' / '),explanation,level:'basic'};
  }
